#!/usr/bin/env node
/**
 * Patches worker-configuration.d.ts (auto-generated by `wrangler types`) to fix
 * the Body.json() return type. Wrangler's generated types declare:
 *   json<T>(): Promise<T>;
 * which defaults T to `unknown`, breaking 200+ call sites that expect `any`
 * (matching the DOM lib's Response.json(): Promise<any> signature).
 *
 * This script replaces the generic signature with the non-generic `Promise<any>`
 * form, restoring compatibility with the codebase's existing fetch().json() usage.
 *
 * Run automatically as part of cf:prepare / cf:build / cf:preview / cf:deploy.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const typesFile = path.join(projectRoot, 'worker-configuration.d.ts');

if (!existsSync(typesFile)) {
  console.log('[patch-wrangler-types] worker-configuration.d.ts not found — skipping');
  process.exit(0);
}

let content = readFileSync(typesFile, 'utf8');

// Match: json<T>(): Promise<T>;  →  json(): Promise<any>;
// Escaped parens \(\) are literal; the generic <T> and Promise<T> must match exactly.
const GENERIC_JSON = /json<\s*T\s*>\(\)\s*:\s*Promise<\s*T\s*>;/g;
const NON_GENERIC = 'json(): Promise<any>;';

if (GENERIC_JSON.test(content)) {
  // Reset lastIndex after .test() with /g flag
  GENERIC_JSON.lastIndex = 0;
  content = content.replace(GENERIC_JSON, NON_GENERIC);
  writeFileSync(typesFile, content, 'utf8');
  console.log('[patch-wrangler-types] Patched Body.json<T>(): Promise<T> → json(): Promise<any>');
} else {
  console.log('[patch-wrangler-types] Already patched (or pattern not found) — no changes');
}
